            Map(m => m.AreaCode)        .Name("AreaCode");
            Map(m => m.DistrictName)    .Name("DistrictName");
            Map(m => m.DistrictNumber)  .Name("DistrictNumber");
            Map(m => m.DeliveryZipCode) .Name("DeliveryZipCode");
