builder.Services.AddSingleton<SignalRTelemetrySink>(sp =>
    new SignalRTelemetrySink(
        sp.GetRequiredService<IHubContext<SignalRInternalTelemetryHub>>(),
        sp.GetRequiredService<IHubContext<SignalRInternalLoggingHub>>()
    )
);
```

