        private readonly IHubContext<SignalRInternalLoggingHub>   _logging;

        public SignalRTelemetrySink(
            IHubContext<SignalRInternalTelemetryHub> telemetryHub,
            IHubContext<SignalRInternalLoggingHub>   loggingHub
        )
